// F-03: the invoice chases itself at 7 / 30 / 60 / 90 days instead of living
// in somebody's private spreadsheet of who owes what.
const cfg = $('Config').first().json;
const STEPS = [7, 30, 60, 90];
const users = $('Get Users').all().map(u => u.json);
const director = users.find(u => /director|owner/i.test(String(u.role || '')));
const byName = (nm) => {
  const k = String(nm || '').trim().toLowerCase();
  return k ? users.find(u => String(u.full_name || '').toLowerCase() === k) : null;
};

const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const age = Number(r.age_days);
  // chase on the step days, then every 7th day after 90
  const onStep = STEPS.includes(age) || (age > 90 && (age - 90) % 7 === 0);
  if (!onStep) continue;

  const severity = age >= 90 ? 'FINAL' : age >= 60 ? 'SECOND' : age >= 30 ? 'FIRST' : 'DUE';
  const person = byName(r.owed_to);
  const url = `${cfg.portal_url}/record/${r.form_code}/${r.id}`;

  out.push({ json: {
    channel: age >= 60 ? 'email,whatsapp,slack' : 'email',
    to_email: cfg.finance_email,
    slack_channel: 'dharani-finance',
    subject: `[${severity} NOTICE - ${age}d] ${r.form_title} ${r.reference}`,
    message:
`${r.form_title} ${r.reference} has been outstanding for ${age} days.

Document : ${r.doc_no}
Status   : ${r.status}
Owed to  : ${r.owed_to || 'not named on the record'}${person ? ' (' + person.email + ')' : ''}
${Number(r.amount) > 0 ? 'Amount   : AED ' + Number(r.amount).toLocaleString() + '\n' : ''}Raised   : ${age} days ago
${r.due_txt ? 'Dated    : ' + r.due_txt + '\n' : ''}
Open it: ${url}

${age >= 90
  ? 'This is the final automated notice. It now goes to the Director as well and will repeat weekly until the status is Paid.'
  : 'Move the record to Paid and this stops by itself.'}`,
  }});

  if (age >= 90 && director) {
    out.push({ json: {
      channel: 'email',
      to_email: director.email,
      subject: `[90+ DAYS] ${r.form_title} ${r.reference} still unpaid`,
      message: `${r.reference} (${r.doc_no}) is ${age} days old and still ${r.status}.\n\n${url}`,
    }});
  }
}
return out;
